static <T> List<T> replicate(List<T> list, int n) {
    List<T> result = new ArrayList<>();
    for (T item : list) {
        for (int i = 0; i < n; i++) result.add(item);
    }
    return result;
}

System.out.println(replicate(List.of("a", "b", "c"), 3));

