static boolean isAnagram(String a, String b) {
    if (a.length() != b.length()) return false;
    char[] ca = a.toCharArray();
    char[] cb = b.toCharArray();
    java.util.Arrays.sort(ca);
    java.util.Arrays.sort(cb);
    return java.util.Arrays.equals(ca, cb);
}

System.out.println(isAnagram("listen", "silent"));
System.out.println(isAnagram("hello", "world"));

static int countInversions(List<Integer> list) {
    int count = 0;
    for (int i = 0; i < list.size(); i++) {
        for (int j = i + 1; j < list.size(); j++) {
            if (list.get(i) > list.get(j)) count++;
        }
    }
    return count;
}

System.out.println(countInversions(List.of(3, 1, 2)));
System.out.println(countInversions(List.of(1, 2, 3, 4)));
System.out.println(countInversions(List.of(4, 3, 2, 1)));

